import{THANE_CREEK_DATA}from"./thane-creek-data.js";function initTheme(){const t=document.getElementById("theme-toggle");t&&t.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");localStorage.setItem("theme",e?"light":"dark"),t.textContent=e?"🌙":"☀️"})}function initNavbar(){const t=document.getElementById("menu-toggle"),e=document.getElementById("nav-menu");t&&e&&t.addEventListener("click",()=>{const n="true"===t.getAttribute("aria-expanded");t.setAttribute("aria-expanded",!n),e.classList.toggle("active")})}function renderStats(){const t=document.getElementById("stats-grid");t&&THANE_CREEK_DATA.stats&&(t.innerHTML=THANE_CREEK_DATA.stats.map(t=>`\n        <div class="stat-card">\n            <span class="stat-icon">${t.icon}</span>\n            <div class="stat-value">${t.value}</div>\n            <div class="stat-label">${t.label}</div>\n        </div>\n    `).join(""))}function renderHistory(){const t=document.getElementById("history-title"),e=document.getElementById("history-content");t&&(t.textContent=THANE_CREEK_DATA.history.title),e&&(e.textContent=THANE_CREEK_DATA.history.content)}function renderRamsar(){const t=document.getElementById("ramsar-title"),e=document.getElementById("ramsar-content");t&&(t.textContent=THANE_CREEK_DATA.ramsarSite.title),e&&(e.textContent=THANE_CREEK_DATA.ramsarSite.content)}function renderMangrove(){const t=document.getElementById("mangrove-title"),e=document.getElementById("mangrove-content");t&&(t.textContent=THANE_CREEK_DATA.mangroveEcosystem.title),e&&(e.textContent=THANE_CREEK_DATA.mangroveEcosystem.content)}function renderFlamingos(){const t=document.getElementById("flamingo-title"),e=document.getElementById("flamingo-content"),n=document.getElementById("flamingo-facts");t&&(t.textContent=THANE_CREEK_DATA.flamingos.title),e&&(e.textContent=THANE_CREEK_DATA.flamingos.content),n&&THANE_CREEK_DATA.flamingos.facts&&(n.innerHTML=THANE_CREEK_DATA.flamingos.facts.map(t=>`<div class="fact-bullet">🦩 ${t}</div>`).join(""))}function renderBiodiversity(){const t=document.getElementById("biodiversity-title"),e=document.getElementById("biodiversity-content");t&&(t.textContent=THANE_CREEK_DATA.marineBiodiversity.title),e&&(e.textContent=THANE_CREEK_DATA.marineBiodiversity.content)}function renderConservation(){const t=document.getElementById("conservation-title"),e=document.getElementById("conservation-content");t&&(t.textContent=THANE_CREEK_DATA.conservation.title),e&&(e.textContent=THANE_CREEK_DATA.conservation.content)}function renderMapHotspots(){const t=document.getElementById("hotspots-list");t&&THANE_CREEK_DATA.hotspots&&(t.innerHTML=THANE_CREEK_DATA.hotspots.map((t,e)=>`\n        <button class="spot-btn ${0===e?"active":""}" data-id="${t.id}">\n            <span class="spot-name">${t.name}</span>\n        </button>\n    `).join(""),showHotspotDetail(THANE_CREEK_DATA.hotspots[0]),t.addEventListener("click",t=>{const e=t.target.closest(".spot-btn");if(!e)return;const n=e.getAttribute("data-id"),o=THANE_CREEK_DATA.hotspots.find(t=>t.id===n);document.querySelectorAll(".spot-btn").forEach(t=>t.classList.remove("active")),e.classList.add("active"),o&&showHotspotDetail(o)}))}function showHotspotDetail(t){const e=document.getElementById("hotspot-detail");e&&(e.innerHTML=`\n        <h3 style="margin: 0 0 0.5rem; color: #ec4899; font-size: 1.5rem;">${t.name}</h3>\n        <p style="color: var(--thane-text-sub); line-height: 1.6; margin-bottom: 1.25rem;">${t.desc}</p>\n        <div style="font-family: monospace; font-size: 0.85rem; color: #94a3b8; background: rgba(0,0,0,0.2); padding: 0.5rem 0.85rem; border-radius: 0.5rem;">Coordinates: ${t.lat}° N, ${t.lng}° E</div>\n    `)}function renderGallery(){const t=document.getElementById("gallery-grid");t&&THANE_CREEK_DATA.gallery&&(t.innerHTML=THANE_CREEK_DATA.gallery.map(t=>`\n        <div class="gallery-card">\n            <img src="${t.url}" alt="${t.title}" loading="lazy" />\n            <div class="gallery-info">\n                <h4>${t.title}</h4>\n                <p>${t.caption}</p>\n            </div>\n        </div>\n    `).join(""))}function renderFacts(){const t=document.getElementById("facts-grid");t&&THANE_CREEK_DATA.facts&&(t.innerHTML=THANE_CREEK_DATA.facts.map(t=>`<div class="trivia-box">💡 ${t}</div>`).join(""))}document.addEventListener("DOMContentLoaded",()=>{initTheme(),initNavbar(),renderStats(),renderHistory(),renderRamsar(),renderMangrove(),renderFlamingos(),renderBiodiversity(),renderConservation(),renderMapHotspots(),renderGallery(),renderFacts()});